    if (length === n) {
      result.push(number);
      return;
    }
    const last = number % 10;
    if (last - k >= 0) {
      extend(number * 10 + (last - k), length + 1);
    }
    if (k > 0 && last + k <= 9) {
      extend(number * 10 + (last + k), length + 1);
    }
  }

  for (let first = 1; first <= 9; first++) {
    extend(first, 1);
  }
  return result;
}

